const IRControls={
 esc:x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),
 list:x=>String(x||'').split('\n').filter(Boolean),
 isMulti:(f,path,s)=>['scope','findings','post','tests','recommendation','procedureSteps'].includes(f.key)||(s.module===0&&f.key==='tip'),
 branches:{'Renal artery':['right renal artery','left renal artery','bilateral renal arteries'],'Internal iliac artery':['right internal iliac artery','left internal iliac artery','bilateral internal iliac arteries'],'Segmental artery':Array.from({length:8},(_,i)=>`segment ${i+1} hepatic artery`),'Intercostal artery':['right','left'].flatMap(side=>Array.from({length:12},(_,i)=>`${side} ${i+1}${i===0?'st':i===1?'nd':i===2?'rd':'th'} intercostal artery`))},
 arteries:['celiac artery','superior mesenteric artery','inferior mesenteric artery','common hepatic artery','proper hepatic artery','right hepatic artery','left hepatic artery','right inferior phrenic artery','left inferior phrenic artery','splenic artery','gastroduodenal artery','left gastric artery','right gastric artery','abdominal aorta'],
 branchChoices(s){return Object.entries(this.branches).filter(([label])=>s?.subtype!=='HAIC'||label==='Segmental artery');},
 arteryChoices(tip=false,s=null){return this.arteries.filter(x=>s?.subtype!=='HAIC'||!['inferior mesenteric artery','splenic artery'].includes(x)).filter(x=>!tip||!['celiac artery','common hepatic artery','superior mesenteric artery','abdominal aorta'].includes(x)).concat(tip?['branch of superior mesenteric artery']:[],...this.branchChoices(s).map(([,children])=>children));},
 button(path,value,label,selected,multi){return `<button type="button" data-path="${this.esc(path)}" data-value="${this.esc(value)}" ${multi?'data-multi="1"':''} aria-pressed="${selected.includes(value)}">${this.esc(label||value)}</button>`;},
 fields(f,value,path,s){
 const multi=this.isMulti(f,path,s),selected=multi?this.list(value):[value],e=this.esc;
 const artery=s.module===0&&(f.key==='scope'||f.key==='tip'||(f.key==='name'&&path.startsWith('items.vessels.'))||f.key==='embolizationSite'||path.startsWith('items.radio.')&&f.key==='target');
 if(artery){const tip=f.key==='tip';const abbreviations={'celiac artery':'Celiac','superior mesenteric artery':'SMA','inferior mesenteric artery':'IMA','common hepatic artery':'CHA','proper hepatic artery':'PHA','right hepatic artery':'RHA','left hepatic artery':'LHA','right inferior phrenic artery':'RIPA','left inferior phrenic artery':'LIPA','splenic artery':'Splenic artery','gastroduodenal artery':'GDA','left gastric artery':'LGA','right gastric artery':'RGA','branch of superior mesenteric artery':'Branch of SMA'};
 const simple=this.arteryChoices(tip,s).filter(x=>!Object.values(this.branches).flat().includes(x));
 return `<div class="field artery"><div class="label" id="f-${path.replaceAll('.','-')}-label">${e(f.label)}${f.required?' *':''}${multi?' · 多選':''}</div><div class="choices">${simple.map(x=>this.button(path,x,abbreviations[x],selected,multi)).join('')}</div>${this.branchChoices(s).map(([label,children])=>`<details class="arteryBranch" ${selected.some(x=>children.includes(x))?'open':''}><summary>${label}${selected.some(x=>children.includes(x))?' ✓':''}</summary><div class="choices">${children.map(x=>this.button(path,x,(x==='right renal artery'||x==='right internal iliac artery'?'R':x==='left renal artery'||x==='left internal iliac artery'?'L':x.startsWith('bilateral')?'Bil':x.replace('hepatic artery','').replace('intercostal artery','')),selected,multi)).join('')}</div></details>`).join('')}<details class="supplement"><summary>補充其他血管${multi?'（每行一項）':''}</summary><textarea data-path="${e(path)}" aria-label="${e(f.label)}補充">${e(value)}</textarea></details></div>`;
 }
 if(multi){const p=IRProfile.get(s);const groups=f.key==='findings'?p.groups:[[f.key==='procedureSteps'?'本項處置步驟':f.key==='post'?'術後結果':f.key==='tests'?'檢體送驗':'追蹤／注意事項',f.key==='procedureSteps'?p.steps:f.key==='post'?['The procedure was performed as described above',...p.post]:f.key==='tests'?['histopathology','cytology','culture']:p.recommend]];
 const known=groups.flatMap(x=>x[1]),custom=this.list(value).filter(x=>!known.includes(x));
 return `<div class="field"><div class="label">${e(f.label)} · 多選</div>${groups.map(([label,opts])=>`<div class="phraseGroup"><small>${e(label)}</small><div class="choices">${opts.map(x=>this.button(path,x,x,selected,true)).join('')}</div></div>`).join('')}<details class="supplement" ${custom.length?'open':''}><summary>補充文字（每行一項）</summary><textarea data-custom-path="${e(path)}" data-known="${e(JSON.stringify(known))}" aria-label="${e(f.label)}補充">${e(custom.join('\n'))}</textarea></details></div>`;
 }
 return '';
 },
 access(s){const e=this.esc;return `<div class="field accessMerged"><div class="label">穿刺側別／途徑 *</div><div class="accessline"><div class="choices" aria-label="穿刺側別">${['right','left'].map(x=>this.button('values.accessSide',x,x==='right'?'R':'L',[s.values.accessSide],false)).join('')}</div><div class="choices" aria-label="穿刺途徑">${IR.activeFields(s).find(f=>f.key==='access').options.map(x=>this.button('values.access',x,({'common femoral artery':'Femoral','radial artery':'Radial','brachial artery':'Brachial','distal radial artery (anatomical snuffbox)':'Snuffbox / distal radial','axillary artery':'Axillary'})[x]||x,[s.values.access],false)).join('')}</div></div></div>`;}
};
